/// <summary>
/// Copy data to target UI builder class
/// </summary>
class ISDAppIntgCopyDataToTargetUIBuilder extends SysOperationAutomaticUIBuilder
{
    ISDAppIntgCopyDataToTargetContract    dataContract;

    DialogField     dialogOperation;
    DialogField     dialogError;
    DialogField     dialogSelected;


}

Method.Source:
/// <summary>
/// Post build method
/// </summary>
public void postBuild()
{
    super();

    dataContract = this.dataContractObject();

    dialogOperation = this.bindInfo().getDialogField(dataContract, methodStr(ISDAppIntgCopyDataToTargetContract,parmDMFOperation));
    dialogError     = this.bindInfo().getDialogField(dataContract, methodStr(ISDAppIntgCopyDataToTargetContract, parmDMFError));
    dialogSelected  = this.bindInfo().getDialogField(dataContract, methodStr(ISDAppIntgCopyDataToTargetContract, parmDMFSelected));

    dialogOperation.registerOverrideMethod(methodStr(FormComboBoxControl, modified), methodStr(ISDAppIntgCopyDataToTargetUIBuilder, activeModified), this);

    this.setAllowEdit();
}

/// <summary>
/// Set dialog fields editable
/// </summary>
public void setAllowEdit()
{
    dialogError.allowEdit(dialogOperation.value() == DMFOperation::Selected);
    dialogSelected.allowEdit(dialogOperation.value() == DMFOperation::Selected);
}

/// <summary>
/// Update dialog fields
/// </summary>
/// <param name = "_formComboBoxControl"></param>
/// <returns></returns>
private boolean activeModified(FormComboBoxControl  _formComboBoxControl)
{
    DMFOperation dmfOperation = _formComboBoxControl.selection();

    dialogError.allowEdit(dmfOperation == DMFOperation::Selected);
    dialogSelected.allowEdit(dmfOperation == DMFOperation::Selected);

    return true;
}
